#include <stdio.h>

char a[5][5] = {"0010", "1111", "1100", "0111"};
int b;

void f(int p, int q, int r) {
    if(p < 0 || q < 0 || p >= 4 || q >= 4) return;
    if(a[p][q] == '0') return;
    b += r;

    a[p][q] = '0';
    f(p-1, q, r+1);
    f(p+1, q, r+1);
    f(p, q-1, r+1);
    f(p, q+1, r+1);
}

int main()
{
    for(int i=0 ; i<4 ; i++) {
        for(int j=0 ; j<4 ; j++) {
            if(a[i][j] == '1') {
                f(i, j, 1);
            }
        }
    }
    printf("%d\n", b);
    return 0;
}

#include <stdio.h>

#define M(A, B) (A > B ? B : A)
#define N(A, B) (A ^ B == 0)
#define P(A, B) (A > B ? A : B)

int n, m;
int mapp[8][8];

int main(void) {
    int f = 1;
    scanf("%d %d", &n, &m);

    for(int i=0 ; i<n ; i++) {
        for(int j=0 ; j<m ; j++) {
            scanf("%1d", &mapp[i][j]);
        }
    }

    for(int k = M(n, m) ; k >= 2 ; k--) {
        for(int i=0 ; i<=n-k ; i++) {
            for(int j=0 ; j<=m-k ; j++) {
                if(N(N(mapp[i][j], mapp[i+k-1][j]),
                    N(mapp[i][j+k-1], mapp[i+k-1][j+k-1]))) {
                    f = P(f, k * k);
                }
            }
        }
    }

    printf("%d\n", f);
    return 0;
}

problems.teacherExplainMd:
3차원 다중 반복문을 이용해 두 행렬(Matrix)을 서로 곱셈 계산하는 수학 알고리즘 코드입니다.

제일 안쪽 줄의 `c += a[i][k] * b[k][j];` 코드가 바로 행렬 곱셈의 공식(앞 행렬의 가로줄 원소들과 뒤 행렬의 세로줄 원소들을 각각 곱해서 더함)을 의미합니다.

이 코드는 한 개의 결과값이 아니라 3번x3번 = 9번 동안 새로 `c`를 계산해서 9개의 숫자를 공백을 두고 출력합니다. 손으로 모든 값을 곱해서 첫 줄을 구해보면:
- 배열 `a`의 0번째 행: {1, 2, 0}
- 배열 `b`의 각 열들: {1, 0, 2}, {-1, 1, 0}, {2, 1, 1}
결과: `1*1+2*0+0*2 = 1` 등 순서대로 계산되어 `1 1 4 5 -1 4 4 1 3` 이 쫙 출력됩니다.

