#include <stdio.h>
int mapp[10][10], w, h;
int ans;
void f(int x, int y) {
    if(x < 1 || x > w || y < 1 || y > h) return;
    if(!mapp[x][y]) return;
    mapp[x][y] = 0;
    for(int i=-1 ; i<=1 ; i++) {
        for(int j=-1 ; j<=1 ; j++) {
            f(x+i, y+j);
        }
    }
}
int main()
{
    scanf("%d %d", &h, &w);
    for(int i=1 ; i<=w ; i++) {
        for(int j=1 ; j<=h ; j++) {
            scanf("%d", &mapp[i][j]);
        }
    }
    for(int i=1 ; i<=w ; i++) {
        for(int j=1 ; j<=h ; j++) {
            if(mapp[i][j]) {
                ans++;
                f(i, j);
            }
        }
    }
    printf("%d", ans);
}

